-- hrm.leave_ledger: Intra-group transfer posts transfer_out on the old employment and transfer_in on the new one with the same source_id (FR-XM-30).
drop function if exists hrm.todo_leave_ledger_transfer();
create or replace function hrm.tg_leave_ledger_transfer() returns trigger
language plpgsql as $fn$
begin
    if new.kind not in ('transfer_in', 'transfer_out') or new.reverses_entry_id is not null then
        return new;
    end if;
    if new.source_id is null or new.source_type is null then
        raise exception 'leave ledger: a transfer entry names its transfer'
            using errcode = '23514', constraint = 'ck_leave_ledger_transfer';
    end if;
    if new.kind = 'transfer_in' and not exists (
           select 1 from hrm.leave_ledger o
           join hrm.employments eo on eo.id = o.employment_id
           join hrm.employments en on en.id = new.employment_id
           where o.source_type = new.source_type and o.source_id = new.source_id and o.kind = 'transfer_out'
             and o.quantity = -new.quantity and o.employment_id <> new.employment_id and eo.person_id = en.person_id) then
        raise exception 'leave ledger: transfer_in % has no transfer_out of the same transfer and quantity on another employment of the person', new.id
            using errcode = '23514', constraint = 'ck_leave_ledger_transfer';
    end if;
    return new;
end
$fn$;
drop trigger if exists tg_leave_ledger_transfer on hrm.leave_ledger;
create trigger tg_leave_ledger_transfer before insert on hrm.leave_ledger
    for each row execute function hrm.tg_leave_ledger_transfer();
