-- hrm.leave_request_days: trigger: sum(quantity) per (employment_id, leave_date) over non-cancelled requests <= 1 day (or shift hours for hourly leave)
drop function if exists hrm.todo_leave_request_days_daily_total();
create or replace function hrm.tg_leave_request_days_daily_total() returns trigger
language plpgsql as $fn$
declare
    v_days numeric(19,6);
    v_hours numeric(19,6);
    v_modifies uuid;
    v_in_hours boolean;
begin
    if new.request_status not in ('submitted', 'approved', 'cancel_requested') then
        return new;
    end if;
    perform pg_advisory_xact_lock(hashtextextended('hrm.leave_days:' || new.employment_id::text, 0));
    select r.modifies_request_id, t.counting = 'hours' into v_modifies, v_in_hours
      from hrm.leave_requests r join hrm.leave_types t on t.id = r.leave_type_id where r.id = new.leave_request_id;
    select coalesce(sum(d.quantity) filter (where t.counting <> 'hours'), 0), coalesce(sum(d.quantity) filter (where t.counting = 'hours'), 0)
      into v_days, v_hours
      from hrm.leave_request_days d
      join hrm.leave_requests r on r.id = d.leave_request_id
      join hrm.leave_types t on t.id = r.leave_type_id
     where d.employment_id = new.employment_id and d.leave_date = new.leave_date and d.id <> new.id
       and d.request_status in ('submitted', 'approved', 'cancel_requested')
       and d.leave_request_id <> new.leave_request_id
       and (v_modifies is null or d.leave_request_id <> v_modifies)
       and r.modifies_request_id is distinct from new.leave_request_id;
    if coalesce(v_in_hours, false) then
        v_hours := v_hours + new.quantity;
    else
        v_days := v_days + new.quantity;
    end if;
    if v_days > 1 or v_hours > 24 or (v_days >= 1 and v_hours > 0) then
        raise exception 'leave: % is already on leave for employment % (days %, hours %)', new.leave_date, new.employment_id, v_days, v_hours
            using errcode = '23514', constraint = 'ck_leave_request_days_daily_total';
    end if;
    return new;
end
$fn$;
drop trigger if exists tg_leave_request_days_daily_total on hrm.leave_request_days;
create trigger tg_leave_request_days_daily_total before insert or update on hrm.leave_request_days
    for each row execute function hrm.tg_leave_request_days_daily_total();
comment on table hrm.leave_request_days is 'Day-by-day breakdown used by attendance and payroll. Requirements: LVE-04, LVE-07. Rule (implemented in S1.32b): trigger: sum(quantity) per (employment_id, leave_date) over non-cancelled requests <= 1 day (or shift hours for hourly leave) Source: hrm-time.yaml.';
comment on column hrm.leave_request_days.leave_request_id is 'fk hrm.leave_requests';
comment on column hrm.leave_request_days.employment_id is 'fk hrm.employments';
comment on column hrm.leave_request_days.request_status is 'copy of leave_requests.status';
